import {mainQuery} from '@github-ui/react-core/future/main-query'
import {branchProtectionsReadOnlyAppBuilder} from '../config/app-builder'
import type {ShowResponse} from '../types'

export const showRoute = branchProtectionsReadOnlyAppBuilder.createQueryRouteConfig('showRoute', {
  path: '/:owner/:repo/branch-protections/:id',
  queries: [mainQuery<ShowResponse>()],
})

export const showStafftoolsRoute = branchProtectionsReadOnlyAppBuilder.createQueryRouteConfig('showStafftoolsRoute', {
  path: '/stafftools/repositories/:owner/:repo/branch-protections/:id',
  queries: [mainQuery<ShowResponse>()],
})
