import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useIsStafftools} from '../contexts/IsStafftoolsProvider'
import {indexRoute, indexStafftoolsRoute} from '../routes/index-route'

export const useIndexRouteQuery = () => {
  const isStafftools = useIsStafftools()
  const route = (isStafftools ? indexStafftoolsRoute : indexRoute) as typeof indexRoute
  return useRouteQuery(route, 'mainQuery')
}
